private void CreateTile(int x, int y)
{
    GameObject tile = Instantiate(TilePrefab);

    SetTileTransform(tile.transform, x, y);
    RegisterTileCoordinate(tile, x, y);
    SetupTileVisuals(tile, x, y);
}

Vector3 worldPosition = new Vector3(
    MapStartX + TileWidthSize * (x + 0.5f),
    MapStartY + TileHeightSize * (y + 0.5f),
    1f
);

tileTransform.position = worldPosition;
mapData[x, y].worldPosition = worldPosition;

// 타일 생성 시 연결
tileDataByCollider[tileCollider] = mapData[x, y];

// 클릭한 콜라이더로 조회
if (!tileDataByCollider.TryGetValue(
        tileCollider, out TileData tile))
    return false;

x = tile.x;
y = tile.y;
return true;

fill.color = (x + y) % 2 == 0
    ? CheckerColor
    : Color.clear;

if (tileColor != null)
    tileColor.AddTile(x, y, fill, damageText);

// BattlePreview.AddTile()
tileFill[x, y] = fill;
tileText[x, y] = tileDamage;
originalTileColors[x, y] = fill.color;

if (currentDistance >= PlayerMovePower)
    continue;

if (!map.TryGetTile(nx, ny, out TileData tile))
    continue;
if (isVisited[nx, ny])
    continue;
if (!tile.Visitable || !tile.CanPlayerGo)
    continue;

isVisited[nx, ny] = true;
distance[nx, ny] = currentDistance + 1;
queue.Enqueue(neighborTile);

// CanMoveTo()의 핵심 조건
reachableTiles[x, y]
&& map.TryGetTile(x, y, out TileData tile)
&& tile.Visitable
&& tile.CanPlayerGo
&& !tile.OnEnemy

// ShowMovePreview()
if (moveRange[x, y] && CanMoveTo(x, y))
    Paint(x, y, movePreviewColor);

int dx = lastTileX - playerTile.x;
int dy = lastTileY - playerTile.y;

if (Mathf.Abs(dy) > Mathf.Abs(dx))
{
    // dy > 0이면 위, 그 외에는 아래
}
else
{
    // dx > 0이면 오른쪽, 그 외에는 왼쪽
}

foreach (AttackCell attackCell in weapon.weaponRD)
{
    Vector2Int targetTile = attackCell.cell;
    Vector2Int getMouseDirection =
        playerTile + GetMouseDirection(targetTile);

    Paint(getMouseDirection.x,
          getMouseDirection.y,
          attackPreviewColor);
}

if (battle.CurrentStep !=
    Battle.Battle_Step.SelectAttack)
    return;
if (currentWeapon == null)
    return;

Vector2Int direction = GetMouseDirection(Vector2Int.up);
if (direction == lastDirection)
    return;

lastDirection = direction;
PlayerAttackPreview(currentWeapon);
